package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="responses") public class Response { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="response_text",nullable=false) private String responseText; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="responded_by_user_id") private User respondedByUser; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="complaint_id") private Complaint complaint; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="investigation_id") private Investigation investigation; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="regional_event_id") private RegionalEvent regionalEvent; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public String getResponseText(){return responseText;} public void setResponseText(String v){responseText=v;} }
